// Determine which files were uploaded and route accordingly
const input = $input.first().json;

const hasExcel = input['Investment File (Excel)'] && 
                 input['Investment File (Excel)'].length > 0;
const hasPdf = input['IC Memo (PDF)'] && 
               input['IC Memo (PDF)'].length > 0;

return [{
  json: {
    ...input,
    hasExcel: hasExcel,
    hasPdf: hasPdf,
    processingMode: hasExcel && hasPdf ? 'both' : (hasExcel ? 'excel' : (hasPdf ? 'pdf' : 'none')),
    analyst: input['Analyst Name'],
    dealName: input['Deal Name'],
    notes: input['Notes'] || '',
    uploadedAt: new Date().toISOString()
  }
}];

// Add compute_marker column to all Excel rows
const items = $input.all();
const metadata = $('Analyze Upload').first().json;

for (const item of items) {
  item.json.compute_marker = 1;
  item.json._analyst = metadata.analyst;
  item.json._deal_name = metadata.dealName;
  item.json._processed_at = new Date().toISOString();
}

return items;

// Parse AI extraction and format for Excel
const aiResponse = $input.first().json;
const metadata = $('Analyze Upload').first().json;

let extractedData;
try {
  const content = aiResponse.message?.content || aiResponse.content || JSON.stringify(aiResponse);
  extractedData = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  // Regex fallback for investment amount
  const text = JSON.stringify(aiResponse);
  const patterns = [
    /\$([\d,]+(?:\.\d+)?)(\s*(?:million|mn|m|billion|bn|b))?/i,
    /USD\s*([\d,]+(?:\.\d+)?)(\s*(?:million|mn|m|billion|bn|b))?/i,
    /([\d,]+(?:\.\d+)?)\s*(?:million|mn|m|billion|bn|b)\s*(?:USD|dollars)?/i
  ];

  let amount = 0;
  for (const pattern of patterns) {
    const match = text.match(pattern);
    if (match) {
      amount = parseFloat(match[1].replace(/,/g, ''));
      const multiplier = (match[2] || '').toLowerCase().trim();
      if (multiplier.startsWith('m')) amount *= 1000000;
      else if (multiplier.startsWith('b')) amount *= 1000000000;
      break;
    }
  }

  extractedData = {
    investment_amount: amount,
    currency: 'USD',
    extraction_method: 'regex_fallback',
    confidence: 0.3
  };
}

return [{
  json: {
    deal_name: metadata.dealName,
    analyst: metadata.analyst,
    investment_amount: extractedData.investment_amount,
    currency: extractedData.currency || 'USD',
    target_company: extractedData.target_company || 'N/A',
    investment_type: extractedData.investment_type || 'N/A',
    investment_stage: extractedData.investment_stage || 'N/A',
    target_irr: extractedData.target_irr || null,
    thesis_summary: extractedData.thesis_summary || 'N/A',
    confidence: extractedData.confidence || 0.5,
    compute_marker: 1,
    source: 'IC_Memo_PDF',
    processed_at: new Date().toISOString(),
    notes: metadata.notes
  }
}];

// Merge PDF investment data into Excel rows with compute_marker
const items = $input.all();
const metadata = $('Analyze Upload').first().json;

// Separate Excel data from AI extraction
const excelRows = items.filter(item => !item.json.message?.content);
const aiData = items.find(item => item.json.message?.content);

let pdfExtract = {};
if (aiData) {
  try {
    const content = aiData.json.message?.content;
    pdfExtract = typeof content === 'string' ? JSON.parse(content) : content;
  } catch (e) {
    pdfExtract = { investment_amount: 0, currency: 'USD' };
  }
}

// Add compute_marker and PDF data to all Excel rows
const result = excelRows.map((item, index) => {
  return {
    json: {
      ...item.json,
      compute_marker: 1,
      ic_memo_investment_amount: pdfExtract.investment_amount || 0,
      ic_memo_currency: pdfExtract.currency || 'USD',
      ic_memo_target_company: pdfExtract.target_company || 'N/A',
      ic_memo_investment_type: pdfExtract.investment_type || 'N/A',
      ic_memo_confidence: pdfExtract.confidence || 0,
      _analyst: metadata.analyst,
      _deal_name: metadata.dealName,
      _processed_at: new Date().toISOString()
    }
  };
});

return result;
